import{_ as t,C as n,o as d,c as i,a8 as o,E as r}from"./chunks/framework.BqC7ICod.js";const w=JSON.parse('{"title":"Demo","description":"Everything below runs in your browser. The controls are the options randName, randNickname, randWord, randSentence and randLocation actually take, the code…","frontmatter":{},"headers":[],"relativePath":"demo.md","filePath":"en/demo.md","lastUpdated":1789273029000}'),c={name:"demo.md"};function s(h,e,l,g,u,m){const a=n("Demo",!0);return d(),i("div",null,[e[0]||(e[0]=o('<h1 id="demo" tabindex="-1">Demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Demo&quot;">​</a></h1><p>Everything below runs in your browser. The controls are the options <code>randName</code>, <code>randNickname</code>, <code>randWord</code>, <code>randSentence</code> and <code>randLocation</code> actually take, the code block under the output is the call your settings amount to, and what you see is drawn fresh every time you press Generate.</p>',2)),r(a),e[1]||(e[1]=o('<h2 id="what-to-try" tabindex="-1">What to try <a class="header-anchor" href="#what-to-try" aria-label="Permalink to &quot;What to try&quot;">​</a></h2><ul><li>Set <code>language</code> to <code>en</code> and <code>realism</code> to <code>invented</code>. The names still read as English and stop being names anybody has — the generator builds them out of syllable templates instead of drawing from the pool.</li><li>Leave <code>language</code> on <code>all</code> and press Generate a few times. Nine scripts, and each name&#39;s length range is resolved for its own language rather than for the batch.</li><li>Pick <code>ru</code> and switch <code>gender</code>. Russian is the one language where the choice is visible from the outside: the patronymic and the surname both inflect.</li><li>On the nickname tab, set <code>theme</code> to <code>animal</code> and <code>wordSeparator</code> to <code>-</code>. The separator counts toward the length range, so a narrow range drops the modifier rather than truncating a word.</li><li>Set <code>maxLength</code> to <code>8</code> on an English nickname. The three-word shapes drop out rather than being truncated — length picks the shape, not the words.</li><li>Turn on <code>randSuffix</code>. The token is attached after the nickname is finished, which is why the length options never have to account for it.</li><li>On the words tab, pick a <code>theme</code> and press Generate. These are the pools a nickname is built from, handed over with nothing added — <code>randAnimal</code> and its twenty-eight siblings are this call with the theme already chosen.</li><li>Switch the decorator to <code>randModifier</code> on the words tab. A modifier in front of a noun is most of what <code>randNickname</code> does, and the code block shows the two functions doing it in the open.</li><li>On the sentence tab, set <code>language</code> to <code>de</code> and then to <code>ru</code>, and turn on the details. Neither language offers an <code>object</code> or a <code>place</code>: both would put the noun in a case its own ending has to change for, so those shapes are not among the ones they declare.</li><li>Type two words into <code>include</code> — <code>brave lion</code> in English, <code>사자 조용히</code> in Korean. Both land in every sentence, and <code>brave</code> becomes a modifier or a predicate depending on what the rest of the shape has room for.</li><li>Set <code>shape</code> to <code>simple</code> and then to <code>complex</code>. The sentence gains a phrase rather than a longer word, which is the same thing <code>minLength</code> does one character at a time.</li><li>On the locations tab, turn on the details and press Generate a few times. Every district sits inside the city beside it and every city inside its region, because each is one the country publishes rather than a name put together.</li><li>Leave <code>randLocation</code> picked, set <code>language</code> to <code>ko</code> and turn off <code>includeCountry</code>. The country stops opening every line, and <code>startsWith</code> on <code>서</code> now draws from 서울특별시 rather than matching nothing.</li><li>Pick <code>randDistrict</code> and set <code>language</code> to <code>en</code>. Nothing comes back: a US location stops at the city, and only Korean has a level below it. Leave <code>language</code> on <code>all</code> and the same call draws Korean alone.</li><li>Pick <code>randRegion</code>, set <code>language</code> to <code>ko</code>, <code>count</code> to <code>20</code> and turn on <code>unique</code>. Sixteen come back, which is every 시·도 there is.</li><li>Pick <code>randCountry</code> and set <code>language</code> to <code>ja</code>, then turn on the details. Every country and territory ISO 3166-1 codes has a name in all nine languages, so this is the one location function that is not held to Korean and English.</li><li>Pick <code>randCity</code> with <code>language</code> on <code>ko</code> and <code>startsWith</code> on <code>수</code>. A 구 that is one of a city&#39;s districts is written with its city, <code>수원시 장안구</code>, the way an address writes it.</li></ul><h2 id="what-this-page-is-not" tabindex="-1">The scope of this page <a class="header-anchor" href="#what-this-page-is-not" aria-label="Permalink to &quot;The scope of this page {#what-this-page-is-not}&quot;">​</a></h2><p>This page is a demonstration rather than a generator to call from a browser at scale. The library itself has no network calls and no dependencies, so the same code runs on a server, in a build script or in a test fixture exactly as it runs here.</p><p>The page draws <strong>without a seed</strong>, so pressing Generate twice gives two different batches. Your own calls do not have to: every generator takes a <code>random</code>, and a seeded one hands back the same batch on every run. <a href="./guide/getting-started#choosing-the-source">Choosing the source</a> shows how.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./guide/getting-started">Getting started</a> — installing it, for whichever of the three packages you use.</li><li><a href="./name/rand-name"><code>randName</code></a>, <a href="./nickname/rand-nickname"><code>randNickname</code></a>, <a href="./word/rand-word"><code>randWord</code></a>, <a href="./sentence/rand-sentence"><code>randSentence</code></a> and <a href="./location/rand-location"><code>randLocation</code></a> — every option in the panel above, written out.</li><li><a href="./guide/languages">Supported languages</a> — what each language can and cannot do.</li></ul>',7))])}const f=t(c,[["render",s]]);export{w as __pageData,f as default};
